parts.append('</div><div class="stage-panels">')
for i,(sid,name,ko,desc,boss,shot,laser,bossfile) in enumerate(stages):
    parts.append(f'<article class="stage-panel" data-stage-panel="{i}"'+(' hidden' if i else '')+'><div class="stage-scene">'+image(sid+'-bg',name+'에 사용되는 일반 배경','stage-bg')+image(sid+'-boss',boss+' 실제 보스 자산','stage-boss')+f'<div class="stage-label"><span>{i+1:02d} / STAGE ART</span><h3>{name}</h3><p>{ko} · {boss}</p></div></div><div class="stage-detail"><p>{desc}</p><dl><div><dt>고유 탄막</dt><dd>{shot}</dd></div><div><dt>레이저 계열</dt><dd>{laser}</dd></div><div><dt>음악과 소리</dt><dd>지역 일반곡 + 보스곡 + 고유 포효</dd></div></dl></div><div class="asset-strip">')
    for k,label in [('normal','일반벽'),('special','특수벽'),('projectile','투사체'),('laser','레이저 자산'),('portal','포털 장식')]:
        parts.append('<figure>'+image(sid+'-'+k,ko+' '+label)+'<figcaption>'+label+'</figcaption></figure>')
    parts.append('</div><p class="note">게임 자산 구성 보드입니다. 실제 배치는 엔진이 생성하며, 레이저의 빛·보스 관절 움직임·포털 전환은 이미지 위에 실시간 효과를 더합니다.</p></article>')
parts.append('</div><div class="split sound-notes"><article><h3>일반곡에서 보스곡으로</h3><p>6개 지역마다 일반곡과 더 긴박한 보스곡, 총 12개 반복곡을 사용합니다. 전환은 짧게 겹쳐 이어주고, 일시정지는 위치를 유지합니다. 음소거는 배경음과 효과음 모두에 적용됩니다.</p></article><article><h3>넓고 낮은 경고음 3회</h3><p>귀여운 비프음 대신 넓게 울리는 기계식 사이렌으로 바꿨습니다. 0.7초 × 3회, 중간 0.15초 간격으로 총 2.4초입니다. 알림·음악 낮추기·재개 위치가 함께 움직입니다.</p><audio controls preload="metadata" aria-label="확정된 보스 진입 사이렌"><source src="data:audio/wav;base64,'+base64.b64encode((ROOT/'public/assets/audio/boss-entry.wav').read_bytes()).decode()+'" type="audio/wav"></audio></article></div></section>')

parts.append('<section id="feedback">'+section_head('07','PLAYTEST → ITERATION','실플레이 피드백이 바꾼 세부사항.','“재미있다”에서 끝내지 않고, 무엇이 왜 불편한지 전달하며 반복했습니다. 아래는 실제 대화와 변경 기록을 현재 버전 관점으로 정리한 '+str(len(feedback))+'개 사례입니다.')+'''<div class="feedback-toolbar"><label class="search-label" for="feedbackSearch">개선 기록 검색<input id="feedbackSearch" type="search" placeholder="예: 히트박스, 기록, 배경, WASD"></label><div class="filter-buttons" role="group" aria-label="피드백 분류">''')
for label in ['전체','화면·디자인','조작·밸런스','전투·연출','신뢰성·성능']:
    parts.append('<button data-filter="'+label+'" aria-pressed="'+('true' if label=='전체' else 'false')+'">'+label+'</button>')
parts.append('</div></div><p id="feedbackCount" class="note" aria-live="polite">'+str(len(feedback))+'개 개선 기록</p><div class="feedback-list">')
