js=r'''
var ChartManager = {
  charts: new Map(),
  safeInit: function(canvasId,config){
    if(typeof Chart==='undefined'){console.error('Chart.js not loaded');return null;}
    try{if(this.charts.has(canvasId)){this.charts.get(canvasId).destroy();this.charts.delete(canvasId);}var ctx=document.getElementById(canvasId);if(!ctx)return null;if(ctx.chart){ctx.chart.destroy();delete ctx.chart;}ctx.setAttribute('role','img');var chart=new Chart(ctx,config);this.charts.set(canvasId,chart);return chart;}catch(error){console.error('Chart initialization failed',error);return null;}
  },
  destroyAll:function(){this.charts.forEach(function(c){c.destroy();});this.charts.clear();}
};
var chartsBuilt=false;
function buildCharts(){
  if(typeof Chart==='undefined'){console.error('Chart.js not loaded');return;}
  if(chartsBuilt)return;
  var style=getComputedStyle(document.documentElement), text=style.getPropertyValue('--text-secondary').trim(),border=style.getPropertyValue('--border').trim(),accent=style.getPropertyValue('--accent').trim(),secondary=style.getPropertyValue('--accent-secondary').trim();
  var canvas=document.getElementById('speedChart');canvas.hidden=false;document.getElementById('speedFallback').setAttribute('hidden','');
  var chart=ChartManager.safeInit('speedChart',{type:'line',data:{labels:[0,20,40,60,80,100,120,140,160,180,200,220],datasets:[{label:'NOVA / AEGIS',data:[240,260,280,300,320,340,360,380,400,420,440,460],borderColor:accent,backgroundColor:accent,borderWidth:3,pointRadius:0,pointHoverRadius:6},{label:'VELOCITY',data:[480,500,520,540,560,580,600,620,640,660,680,700],borderColor:secondary,backgroundColor:secondary,borderWidth:3,pointRadius:0,pointHoverRadius:6}]},options:{responsive:true,maintainAspectRatio:false,animation:false,interaction:{mode:'index',intersect:false},layout:{padding:12},plugins:{tooltip:{enabled:true,padding:12,cornerRadius:8},legend:{labels:{color:text,font:{family:'Inter',size:13},usePointStyle:true}}},scales:{x:{grid:{display:false},ticks:{color:text,maxRotation:0,maxTicksLimit:7,font:{size:13}},title:{display:true,text:'속도용 진행 점수',color:text,font:{size:14}}},y:{min:200,max:750,grid:{color:border},ticks:{color:text,font:{size:13}},title:{display:true,text:'일반 비행 속도 (논리 px/s)',color:text,font:{size:14}}}}}});
  chartsBuilt=Boolean(chart);if(!chart){canvas.hidden=true;document.getElementById('speedFallback').removeAttribute('hidden');}
}
function onThemeChange(){if(chartsBuilt){chartsBuilt=false;buildCharts();}}
var activeFilter='전체';
function filterFeedback(){var q=document.getElementById('feedbackSearch').value.trim().toLowerCase(),count=0;document.querySelectorAll('.feedback-item').forEach(function(item){var visible=(activeFilter==='전체'||item.dataset.category===activeFilter)&&item.textContent.toLowerCase().includes(q);item.hidden=!visible;if(visible)count++;});document.getElementById('feedbackCount').textContent=count+'개 개선 기록';document.getElementById('emptyFeedback').hidden=count!==0;}
document.addEventListener('DOMContentLoaded',function(){
  buildCharts();
  document.querySelectorAll('[data-stage]').forEach(function(button){button.addEventListener('click',function(){var id=button.dataset.stage;document.querySelectorAll('[data-stage]').forEach(function(b){b.setAttribute('aria-pressed',String(b===button));});document.querySelectorAll('[data-stage-panel]').forEach(function(p){p.hidden=p.dataset.stagePanel!==id;});});});
  document.querySelectorAll('[data-filter]').forEach(function(button){button.addEventListener('click',function(){activeFilter=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(function(b){b.setAttribute('aria-pressed',String(b===button));});filterFeedback();});});
  document.getElementById('feedbackSearch').addEventListener('input',filterFeedback);
  document.getElementById('copyVersion').addEventListener('click',async function(){var text='VOID SURFER 0.01v\n기준일: 2026-10-29\n게임 소스: f69a166\n3기체 / 6지역 / 테스트 699개 통과\n상태: 배포 준비 기준';try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(text);else{var box=document.createElement('textarea');box.value=text;document.body.appendChild(box);box.select();if(!document.execCommand('copy'))throw Error('copy unavailable');box.remove();}document.getElementById('copyStatus').textContent='버전 정보를 복사했습니다.';}catch(e){document.getElementById('copyStatus').textContent='VOID SURFER 0.01v · 2026-10-29 · f69a166';}});
  setTimeout(function(){document.querySelectorAll('.reveal').forEach(function(el){el.classList.add('visible');});},500);
});
var printDetails=[];
window.addEventListener('beforeprint',function(){printDetails=[];document.querySelectorAll('details').forEach(function(d){printDetails.push([d,d.open,d.getAttribute('name')]);d.removeAttribute('name');d.open=true;});});
window.addEventListener('afterprint',function(){printDetails.forEach(function(r){r[0].open=r[1];if(r[2])r[0].setAttribute('name',r[2]);});});
'''

